<genre_tragedy>
<genre_tags>Tragedy, Hamartia, Anagnorisis, Earned-Ruin, Fatal-Flaw, Impossible-Obligation, Pyrrhic-Victory, Irreversible-Choice</genre_tags>
<scene_selection>Warning-Ignored, Oath-Becomes-Trap, Mercy-Too-Late, Victory-With-Cost, Public-Fall, Private-Recognition, Farewell-Before-Understanding, Last-Chance-Refused</scene_selection>
<pressure_tags>Pride, Love-As-Doom, Fate-Through-Choice, Social-Trap, False-Belief, Delayed-Recognition, No-Clean-Exit, Cost-Already-Paid</pressure_tags>
<character_roles>Flawed-Hero, Loyal-Destroyer, Loving-Betrayer, Cassandra-Witness, Ruler-Trapped-By-Role, Innocent-Cost, Enemy-Who-Was-Right</character_roles>
<world_behavior>Causality-Tightens, Warnings-Return, Rescue-Arrives-Too-Late, Dignity-Remains, Consequences-Do-Not-Unhappen, Beauty-Sharpens-Loss</world_behavior>
<motif_tags>Broken-Crown, Empty-Seat, Blood-On-Ceremony, Last-Letter, Door-Closed-Softly, Crowd-Falling-Silent, Flower-At-Ruin</motif_tags>
<tone_range>Lucid, Grave, Restrained, Tender, Dreadful, Ceremonial, Devastating, Clear-Eyed</tone_range>
